import unittest
from candidate import remove_vowels

class TestRemoveVowels(unittest.TestCase):
    def test_normal_case_lowercase(self):
        self.assertEqual(remove_vowels("abcdef"), "bcdf")

    def test_normal_case_uppercase(self):
        self.assertEqual(remove_vowels("ABCDEF"), "BCDF")

    def test_mixed_case(self):
        self.assertEqual(remove_vowels("aBcDeF"), "BcdF")

    def test_empty_string(self):
        self.assertEqual(remove_vowels(""), "")

    def test_all_vowels_lowercase(self):
        self.assertEqual(remove_vowels("aeiou"), "")

    def test_all_vowels_uppercase(self):
        self.assertEqual(remove_vowels("AEIOU"), "")

    def test_all_consonants(self):
        self.assertEqual(remove_vowels("bcdfg"), "bcdfg")

    def test_single_vowel(self):
        self.assertEqual(remove_vowels("a"), "")
        self.assertEqual(remove_vowels("e"), "")
        self.assertEqual(remove_vowels("i"), "")
        self.assertEqual(remove_vowels("o"), "")
        self.assertEqual(remove_vowels("u"), "")

    def test_single_consonant(self):
        self.assertEqual(remove_vowels("b"), "b")
        self.assertEqual(remove_vowels("z"), "z")

    def test_newline_and_spaces(self):
        self.assertEqual(remove_vowels("a b\nc\de"), " b\nc d")

    def test_case_insensitivity_with_whitespace(self):
        self.assertEqual(remove_vowels("A b\nC\De"), " b\nC d")

    def test_non_ascii_vowels(self):
        self.assertEqual(remove_vowels("äöü"), "äöü")
        self.assertEqual(remove_vowels("ÀÈÌÒÙ"), "ÀÈÌÒÙ")

    def test_unicode_string(self):
        self.assertEqual(remove_vowels("café"), "cf")
        self.assertEqual(remove_vowels("naïve"), "nv")

    def test_none_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(123)
        with self.assertRaises(TypeError):
            remove_vowels([1, 2, 3])
        with self.assertRaises(TypeError):
            remove_vowels({"a": "b"})

    def test_case_sensitivity_with_whitespace(self):
        self.assertEqual(remove_vowels("AeIoU"), "")

    def test_preserve_non_alphabetic_chars(self):
        self.assertEqual(remove_vowels("a1e2i3o4u5"), "12345")
        self.assertEqual(remove_vowels("!@#aEiOu"), "!@#")

    def test_long_string(self):
        long_text = "a" * 1000 + "b" * 1000
        self.assertEqual(len(remove_vowels(long_text)), 1000)
